package controle;
import conexao.Conexao;import dao.PagamentoDAO;import java.awt.*;import java.math.BigDecimal;import java.time.LocalDate;import javax.swing.*;import javax.swing.table.DefaultTableModel;import modelo.Pagamento;
public class TelaPagamento extends JFrame{private final Conexao con=new Conexao();private PagamentoDAO dao;private final JTextField id=new JTextField(),venc=new JTextField(),dataPg=new JTextField(),valor=new JTextField(),matricula=new JTextField();private final JComboBox<String> situacao=new JComboBox<>(new String[]{"PENDENTE","PAGO","ATRASADO","CANCELADO"});private final DefaultTableModel m=new DefaultTableModel(new String[]{"Código","Vencimento","Pagamento","Valor","Situação","Matrícula"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable t=new JTable(m);public TelaPagamento(){setTitle("Pagamentos");setSize(800,470);setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel p=new JPanel(new GridLayout(6,2,5,5));id.setEditable(false);p.add(new JLabel("Código:"));p.add(id);p.add(new JLabel("Vencimento (AAAA-MM-DD):"));p.add(venc);p.add(new JLabel("Data pagamento (opcional):"));p.add(dataPg);p.add(new JLabel("Valor:"));p.add(valor);p.add(new JLabel("Situação:"));p.add(situacao);p.add(new JLabel("Código matrícula:"));p.add(matricula);JPanel b=new JPanel();for(String s:new String[]{"Novo","Salvar","Excluir","Fechar"}){JButton x=new JButton(s);b.add(x);if(s.equals("Novo"))x.addActionListener(e->limpar());if(s.equals("Salvar"))x.addActionListener(e->salvar());if(s.equals("Excluir"))x.addActionListener(e->excluir());if(s.equals("Fechar"))x.addActionListener(e->dispose());}JPanel n=new JPanel(new BorderLayout());n.setBorder(BorderFactory.createEmptyBorder(10,10,10,10));n.add(p);n.add(b,BorderLayout.SOUTH);add(n,BorderLayout.NORTH);add(new JScrollPane(t));t.getSelectionModel().addListSelectionListener(e->{int r=t.getSelectedRow();if(r>=0&&!e.getValueIsAdjusting()){id.setText(m.getValueAt(r,0).toString());venc.setText(m.getValueAt(r,1).toString());dataPg.setText(m.getValueAt(r,2)==null?"":m.getValueAt(r,2).toString());valor.setText(m.getValueAt(r,3).toString());situacao.setSelectedItem(m.getValueAt(r,4).toString());matricula.setText(m.getValueAt(r,5).toString());}});if(con.conecta()){dao=new PagamentoDAO(con);carregar();}addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosed(java.awt.event.WindowEvent e){con.desconecta();}});}private void carregar(){if(dao==null)return;try{m.setRowCount(0);for(Pagamento x:dao.listar())m.addRow(new Object[]{x.getIdPagamento(),x.getVencimento(),x.getDataPagamento(),x.getValor(),x.getSituacao(),x.getIdMatricula()});}catch(Exception e){erro(e);}}private void limpar(){id.setText("");venc.setText("");dataPg.setText("");valor.setText("");matricula.setText("");situacao.setSelectedIndex(0);}private void salvar(){try{Pagamento x=new Pagamento();x.setVencimento(LocalDate.parse(venc.getText()));x.setDataPagamento(dataPg.getText().isBlank()?null:LocalDate.parse(dataPg.getText()));x.setValor(new BigDecimal(valor.getText().replace(',','.')));x.setSituacao(situacao.getSelectedItem().toString());x.setIdMatricula(Integer.parseInt(matricula.getText()));if(id.getText().isBlank())dao.inserir(x);else{x.setIdPagamento(Integer.parseInt(id.getText()));dao.atualizar(x);}carregar();limpar();}catch(Exception e){erro(e);}}private void excluir(){if(id.getText().isBlank())return;try{dao.excluir(Integer.parseInt(id.getText()));carregar();limpar();}catch(Exception e){erro(e);}}private void erro(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Erro",JOptionPane.ERROR_MESSAGE);}}
